import json,statistics,html
from pathlib import Path
root=Path('benchmark');review=json.loads(Path('/Users/indievision/Downloads/editmap-model-review.json').read_text());q=json.loads((root/'qwen-results.json').read_text());labels=review['referenceLabels'];classes=['ECS','CS','MS','FS','LS'];v={r['index']:r for r in review['results']};scored=[r for r in q['results'] if labels.get(str(r['index'])) in classes]
