 i=r['index'];y=labels.get(str(i),'Unreviewed');vp=v[i]['prediction'];qp=r['prediction'];color=lambda p:'yes' if p==y else 'no' if y in classes else ''
 parts.append(f'<tr><td>{i}</td><td><img src="shot-{i}.jpg" alt="Shot {i}"></td><td>{html.escape(y)}</td><td class="{color(vp)}">{html.escape(vp)}</td><td class="{color(qp)}">{html.escape(qp)}</td><td>{html.escape(r["content"] or "Unknown")}</td></tr>')
